import { createHash, randomUUID } from 'node:crypto';
import { createReadStream, createWriteStream } from 'node:fs';
import { mkdir, rename, rm, stat } from 'node:fs/promises';
import { join } from 'node:path';
import { Transform } from 'node:stream';
import { pipeline } from 'node:stream/promises';

// Private file store (ADR-004). Names are always generated by the server
// (UUID): no path is ever built from user input (A8, path traversal).
//   incoming/<id>   uploads waiting for inspection (quarantine)
//   results/<id>    output of the file-processor for the worker
//   stored/<id>     approved files kept for sending (PDF attachments)

const AREAS = new Set(['incoming', 'results', 'stored']);
const ID_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;

export class FileTooLargeError extends Error {
  constructor() {
    super('file too large');
    this.code = 'FILE_TOO_LARGE';
  }
}

export function createFileStore(dir) {
  function pathOf(area, id) {
    if (!AREAS.has(area) || !ID_PATTERN.test(id)) throw new Error('invalid file reference');
    return join(dir, area, id);
  }

  return {
    pathOf,

    // Streams an upload into incoming/, enforcing the size limit while it
    // arrives and computing its SHA-256. Nothing remains if it fails.
    async saveIncoming(source, { maxBytes }) {
      const id = randomUUID();
      await mkdir(join(dir, 'incoming'), { recursive: true });
      const target = pathOf('incoming', id);
      const partial = `${target}.part`;
      const hash = createHash('sha256');
      let size = 0;
      const meter = new Transform({
        transform(chunk, _encoding, callback) {
          size += chunk.length;
          if (size > maxBytes) return callback(new FileTooLargeError());
          hash.update(chunk);
          return callback(null, chunk);
        },
      });
      try {
        await pipeline(source, meter, createWriteStream(partial, { flags: 'wx', mode: 0o600 }));
        // A stream truncated by the multipart limit ends without error.
        if (source.truncated) throw new FileTooLargeError();
        await rename(partial, target);
      } catch (error) {
        await rm(partial, { force: true });
        throw error;
      }
      return { id, size, sha256: hash.digest('hex') };
    },

    async move(fromArea, toArea, id) {
      await mkdir(join(dir, toArea), { recursive: true });
      await rename(pathOf(fromArea, id), pathOf(toArea, id));
    },

    read(area, id) {
      return createReadStream(pathOf(area, id));
    },

    writer(area, id) {
      return mkdir(join(dir, area), { recursive: true }).then(() => createWriteStream(pathOf(area, id), { flags: 'w', mode: 0o600 }));
    },

    async size(area, id) {
      return (await stat(pathOf(area, id))).size;
    },

    async remove(area, id) {
      await rm(pathOf(area, id), { force: true });
    },
  };
}
